}
function string token(string raw) {
    if (isEmpty(raw)) {
        return "";
    }
    return lowerCase(trim(raw));
}
function string combine(string previous, string next) {
    if (previous == "") {
        return next;
    }
    if (next == "") {
        return previous;
    }
    return previous + "|" + next;
}
function string completeness(integer known, integer missing) {
    if (known == 0) {
